{
  "requirements": [
    {
      "text": "The system shall continuously monitor the health and integrity of all sensors and actuators, and automatically transition to a safe‑stop state if any sensor degrades beyond predefined fault thresholds."
    },
    {
      "text": "The system shall provide the human operator with an unambiguous takeover request (visual, audible, and haptic) at least three seconds before a manual intervention is required, and shall repeat the request until acknowledged."
    },
    {
      "text": "If the operator does not acknowledge the takeover request within the allotted time, the system shall execute an immediate controlled stop that brings the vehicle to a safe halt while avoiding obstacles."
    },
    {
      "text": "The system shall operate only within a clearly defined Operational Design Domain (ODD) – including weather, lighting, road‑marking quality, speed limits, and lane‑type – and shall automatically disengage and transition to safe stop when any ODD condition is violated."
    },
    {
      "text": "The system shall provide functional redundancy for all critical perception, prediction, and planning functions such that a single‑point failure (e.g., loss of a lidar unit) does not compromise safe vehicle control."
    },
    {
      "text": "The system shall perform real‑time validation of object classifications and motion predictions, and shall reject or flag uncertain data to prevent unsafe planning decisions."
    },
    {
      "text": "The system shall incorporate cybersecurity safeguards, including authenticated software updates, encrypted communication, and protection against unauthorized remote access or tampering."
    },
    {
      "text": "The system shall record, with precise timestamps, all sensor inputs, perception outputs, planning decisions, control commands, and operator interactions, and securely store these logs for at least one year for post‑incident analysis."
    },
    {
      "text": "The system shall enforce a maximum vehicle speed that never exceeds the posted speed limit and shall not exceed a configurable ceiling (e.g., 45 mph) without explicit operator authorization."
    },
    {
      "text": "The system shall be validated and verified against an established functional‑safety standard (e.g., ISO 26262 ASIL D), with documented safety audits and periodic testing to ensure continued compliance."
    }
  ]
}
